import { readFile } from "node:fs/promises";
import init, { optimise } from "@jsquash/oxipng/codec/pkg/squoosh_oxipng.js";

let codec;

// Mac2 captures an opaque display in an RGBA PNG. Some model requests reject
// that encoding. Keep the native artifact and change only the model's copy.
export async function modelScreenshot(bytes) {
  // PNG's IHDR color-type byte is 6 for RGBA and 2 for RGB.
  if (bytes[25] !== 6) return bytes;
  codec ??= readFile(
    new URL(
      import.meta.resolve("@jsquash/oxipng/codec/pkg/squoosh_oxipng_bg.wasm"),
    ),
  ).then(init);
  await codec;
  const encoded = optimise(bytes, 0, false, false);
  return encoded[25] === 2 ? Buffer.from(encoded) : bytes;
}
